// RepostRx daily report: sorts Blotato's post list (from the HTTP node) into a plain-text email.
// Read-only: it only reads the answer it's given. It never creates or changes posts.
const SITE = 'https://repostrx-renee.netlify.app';
const OVERDUE_MINUTES = 10;
const DAY_MS = 24 * 60 * 60 * 1000;
const now = Date.now();

const answer = $input.first().json;
if (!Array.isArray(answer.items)) {
  // Unexpected shape: stop with an error so the "couldn't run" email goes out, not a false "0 failed".
  throw new Error('Blotato answered without an items list, so the report could not be built.');
}
const posts = answer.items;

const time = (p) => new Date(p.postTime).getTime();
const when = (iso) => new Date(iso).toLocaleString('en-US', {
  timeZone: 'America/Los_Angeles', weekday: 'short', month: 'short', day: 'numeric',
  hour: 'numeric', minute: '2-digit', timeZoneName: 'short',
});
const who = (p) => (p.account ? p.account.name : 'account no longer connected');
const type = (p) => p.state?.type;
const line = (p) => `- ${when(p.postTime)} · ${who(p)} · Blotato post ${p.id}`;
const overdueCutoff = now - OVERDUE_MINUTES * 60 * 1000;

const failed = posts.filter((p) => type(p) === 'failed' && time(p) >= now - DAY_MS);
const overdue = posts.filter((p) => type(p) === 'scheduled' && time(p) < overdueCutoff);
const published = posts.filter((p) => type(p) === 'published' && time(p) >= now - DAY_MS);
const upcoming = posts
  .filter((p) => type(p) === 'scheduled' && time(p) >= overdueCutoff)
  .sort((a, b) => time(a) - time(b));
const unknown = posts.filter((p) => !['failed', 'scheduled', 'published'].includes(type(p)));

const section = (title, list, detail = () => '') =>
  [`${title} (${list.length})`, ...(list.length ? list.map((p) => line(p) + detail(p)) : ['- None'])].join('\n');

const parts = [
  section('FAILED in the last 24 hours', failed, (p) => `\n  Error: ${p.state.errorMessage || 'Blotato gave no error message'}`),
  section(`OVERDUE: still scheduled more than ${OVERDUE_MINUTES} minutes after its post time`, overdue),
  section('PUBLISHED in the last 24 hours', published, (p) => (p.state.postUrl ? `\n  ${p.state.postUrl}` : '')),
  section('COMING UP in the next 7 days', upcoming),
];
if (unknown.length) parts.push(`NOTE: ${unknown.length} post(s) had a status this report doesn't recognise. Check my.blotato.com.`);
if (failed.length || overdue.length) parts.push(`What to do: paste a failed post's error into Post Doctor at ${SITE}, and look for overdue posts at my.blotato.com.`);
if (answer.cursor) parts.push('NOTE: more than 250 posts in the window, so this report only covers the first 250.');
parts.push(`Checked ${when(new Date(now).toISOString())}. Read-only: this report never creates or changes posts.`);

const subject = `${failed.length || overdue.length ? '⚠ ' : ''}RepostRx daily report: ${failed.length} failed, ${overdue.length} overdue`;
return [{ json: { subject, body: parts.join('\n\n') } }];

